import { createGlobalStyle } from 'styled-components';

export const GlobalStyles = createGlobalStyle`
  html, body {
    margin: 0;
    padding: 0;
    background: #020213;
    font-family: Arial, Helvetica, sans-serif;
  }

  *, *::after, *::before {
    box-sizing: border-box;
  }

  h1, h2, h3 {
    margin: 0;
  }

  a {
    text-decoration: none;
    color: inherit;
  }
`;
